import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

public class Main {
    enum Iso { READ_UNCOMMITTED, READ_COMMITTED, REPEATABLE_READ, SERIALIZABLE }

    static class Table {
        final LinkedHashMap<Integer, Integer> committed = new LinkedHashMap<>();
        final LinkedHashMap<Integer, Integer> pending = new LinkedHashMap<>();
    }

    static class Reader {
        final Iso iso; final Table t; Map<Integer, Integer> snap = null;
        Reader(Iso iso, Table t) { this.iso = iso; this.t = t; }
        private void capture() { if (snap == null) snap = new LinkedHashMap<>(t.committed); }
        Integer read(int id) {
            switch (iso) {
                case READ_UNCOMMITTED:
                    return t.pending.containsKey(id) ? t.pending.get(id) : t.committed.get(id);
                case READ_COMMITTED:
                    return t.committed.get(id);
                default:
                    capture();
                    return snap.get(id);
            }
        }
        int rangeCount() {
            switch (iso) {
                case READ_UNCOMMITTED: {
                    Set<Integer> all = new LinkedHashSet<>(t.committed.keySet());
                    all.addAll(t.pending.keySet());
                    return all.size();
                }
                case READ_COMMITTED:
                case REPEATABLE_READ:
                    return t.committed.size();
                case SERIALIZABLE:
                    capture();
                    return snap.size();
                default:
                    return t.committed.size();
            }
        }
    }

    static boolean dirtyRead(Iso iso) {
        Table t = new Table();
        t.committed.put(1, 100);
        Reader r = new Reader(iso, t);
        r.read(1);                       // 建立快照（RR/SER）
        t.pending.put(1, 200);           // 另一事务未提交的写
        return r.read(1) == 200;
    }

    static boolean nonRepeatableRead(Iso iso) {
        Table t = new Table();
        t.committed.put(1, 100);
        Reader r = new Reader(iso, t);
        Integer a = r.read(1);
        t.committed.put(1, 200);         // 另一事务提交了 UPDATE
        return !Objects.equals(a, r.read(1));
    }

    static boolean phantomRead(Iso iso) {
        Table t = new Table();
        t.committed.put(1, 100);
        Reader r = new Reader(iso, t);
        int a = r.rangeCount();
        t.committed.put(2, 1);           // 另一事务提交了 INSERT
        return a != r.rangeCount();
    }

    public static void main(String[] args) {
        for (Iso iso : Iso.values()) {
            System.out.println(String.format("%-17s dirty=%-5s nonrepeatable=%-5s phantom=%-5s",
                    iso, dirtyRead(iso), nonRepeatableRead(iso), phantomRead(iso)));
        }
    }
}
